SELECT CASE WHEN budget >= 3318000 THEN 'high' WHEN budget >= 974000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(budget) AS total_budget, COUNT(*) AS cnt, SUM(SUM(budget)) OVER (ORDER BY CASE WHEN budget >= 3318000 THEN 'high' WHEN budget >= 974000 THEN 'mid' ELSE 'low' END) AS cumulative_budget FROM departments WHERE budget BETWEEN 1996000 AND 2833000 GROUP BY CASE WHEN budget >= 3318000 THEN 'high' WHEN budget >= 974000 THEN 'mid' ELSE 'low' END
